53	  /**
54	   * Flag used to determine if the error is handled by us and should therefore not be shown to the
55	   * user.
56	   */
57	  public isHandledError = false;
58	
59	  get fullErrorCode() {
60	    return parseErrorCode({ code: this.code, category: this.category });
61	  }
62	
63	  /** Overrides the default `Error.name` property in the format: SB_<CATEGORY>_<CODE>. */
64	  get name() {
65	    const errorName = this._name || this.constructor.name;
66	
67	    return `${this.fullErrorCode} (${errorName})`;
68	  }
