74	  /**
75	   * A collection of sub errors which relate to a parent error.
76	   *
77	   * Sub-errors are used to represent multiple related errors that occurred together. When a
78	   * StorybookError with sub-errors is sent to telemetry, both the parent error and each sub-error
79	   * are sent as separate telemetry events. This allows for better error tracking and debugging.
80	   *
81	   * @example
82	   *
83	   * ```ts
84	   * const error1 = new SomeError();
85	   * const error2 = new AnotherError();
86	   * const parentError = new ParentError({
87	   *   // ... other props
88	   *   subErrors: [error1, error2],
89	   * });
90	   * ```
91	   */
92	  subErrors: StorybookError[] = [];
93	
94	  constructor(props: {
95	    category: string;
96	    code: number;
97	    message: string;
98	    cause?: unknown;
99	    documentation?: boolean | string | string[];
100	    isHandledError?: boolean;
101	    name: string;
102	    /**
103	     * Optional array of sub-errors that are related to this error. When this error is sent to
104	     * telemetry, each sub-error will be sent as a separate event.
105	     */
106	    subErrors?: StorybookError[];
107	  }) {
108	    super(
109	      StorybookError.getFullMessage(props),
110	      props.cause === undefined ? undefined : { cause: props.cause }
111	    );
112	    this.category = props.category;
113	    this.documentation = props.documentation ?? false;
114	    this.code = props.code;
115	    this.isHandledError = props.isHandledError ?? false;
116	    this.name = props.name;
117	    this.subErrors = props.subErrors ?? [];
118	  }
119	
120	  /** Generates the error message along with additional documentation link (if applicable). */
121	  static getFullMessage({
122	    documentation,
123	    code,
124	    category,
125	    message,
126	  }: ConstructorParameters<typeof StorybookError>[0]) {
127	    let page: string | undefined;
128	
129	    if (documentation === true) {
130	      page = `https://storybook.js.org/error/${parseErrorCode({ code, category })}?ref=error`;
131	    } else if (typeof documentation === 'string') {
132	      page = appendErrorRef(documentation);
133	    } else if (Array.isArray(documentation)) {
134	      page = `\n${documentation.map((doc) => `\t- ${appendErrorRef(doc)}`).join('\n')}`;
135	    }
136	
137	    return `${message}${page != null ? `\n\nMore info: ${page}\n` : ''}`;
138	  }
