  OpenServiceNotFoundError,
  OpenServiceStaticPathError,
} from '../../server-errors.ts';
import { createService, createServiceRuntime, resolveStaticPath } from './service-runtime.ts';
import { validateSchema } from './service-validation.ts';
import type {
  AnySchema,
  BuildTaskResult,
  Commands,
  Queries,
  QueryDefinition,
  ServiceDefinition,
  ServiceInstance,
  StaticStore,
} from './types.ts';

type RuntimeServiceDefinition = ServiceDefinition<unknown, Queries<unknown>, Commands<unknown>>;
type RuntimeServiceInstance = ServiceInstance<unknown, Queries<unknown>, Commands<unknown>>;
type RuntimeQueryDefinition = QueryDefinition<unknown, AnySchema, AnySchema>;

/**
 * One registry record keeps both the (override-resolved) definition and its live instance.
 *
 * The definition is retained so introspection helpers (`listServices`, `describeService`) and
 * static builds can operate purely on the global registry, while the instance is the shared handle
 * returned to callers and reused across the environment.
 */
type RegistryEntry = {
  definition: RuntimeServiceDefinition;
  instance: RuntimeServiceInstance;
};

/**
 * Handler-only overrides applied to a definition before it is instantiated.
 *
 * Only the `handler` of each query/command can be swapped; schemas, preloads, and static config are
 * always taken from the original definition so the runtime contract stays intact.
 */
export type ServiceHandlerOverrides<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
> = {
  queries?: Partial<{ [TKey in keyof TQueries]: TQueries[TKey]['handler'] }>;
  commands?: Partial<{ [TKey in keyof TCommands]: TCommands[TKey]['handler'] }>;
};

/** Compact per-service listing entry returned by {@link listServices}. */
export type ServiceSummary = {
  id: string;
  description?: string;
  queryNames: string[];
  commandNames: string[];
};

/** One operation entry (query or command) in a {@link ServiceDescriptor}. */
export type OperationDescriptor = {
  description?: string;
  input: AnySchema;
  output: AnySchema;
};

/** Full descriptor for one service, including schema references for every operation. */
export type ServiceDescriptor = {
  id: string;
  description?: string;
  queries: Record<string, OperationDescriptor>;
  commands: Record<string, OperationDescriptor>;
};

/**
 * The single process-wide registry of server-side services.
 *
 * Because it is module-scoped, any handler or static preload can reach other services through
 * {@link getService}, which is what makes cross-service composition work identically at runtime and
 * during static builds.
 */
const registry = new Map<string, RegistryEntry>();

/**
 * Returns a copy of `operations` where any named handler override replaces the original handler.
 *
 * The rest of each operation definition (schemas, preload, static config) is preserved so overrides
 * cannot silently change a service's validated contract.
 */
function overrideHandlers<TOperations extends Record<string, { handler: unknown }>>(
  operations: TOperations,
  handlerOverrides?: Partial<Record<keyof TOperations, unknown>>
): TOperations {
  if (!handlerOverrides) {
    return operations;
  }

  return Object.fromEntries(
    Object.entries(operations).map(([name, definition]) => {
      const override = handlerOverrides[name as keyof TOperations];

      return [name, override ? { ...definition, handler: override } : definition];
    })
  ) as TOperations;
}

/** Produces a definition with handler overrides applied to its queries and commands. */
function applyHandlerOverrides<
  TState,
  TQueries extends Queries<TState>,
  TCommands extends Commands<TState>,
>(
  definition: ServiceDefinition<TState, TQueries, TCommands>,
  overrides: ServiceHandlerOverrides<TState, TQueries, TCommands>
): ServiceDefinition<TState, TQueries, TCommands> {
  return {
    ...definition,
    queries: overrideHandlers(definition.queries, overrides.queries),
    commands: overrideHandlers(definition.commands, overrides.commands),
  };
